-- Rega24 production data (D1 rega24-migration): Iraq regions and Kurdistan Region / Iraq cities, 2026-10-28.
-- Same rows as prisma/seed-data/geography.ts writes through `npm run db:seed` (checked by tests/seed-data.test.ts).
-- ADDITIVE ONLY: inserts a row only when it is missing (by slug / country + English name / region + locale); it never
-- updates or deletes, and running it again changes nothing. New ids start with seed_region_iq_, seed_rt_iq_ and
-- seed_city_iq_, so the change can be undone exactly by deleting those ids (no business or location refers to them yet).
-- Rehearsed on a disposable D1 copy of the pre-change state: +6 regions, +47 region names, +19 cities, FK check clean,
-- second run no-op, values identical to the seed output (including the folded search columns).
-- Apply (owner, after a D1 Time Travel restore point is noted):
--   node scripts/project-identity-guard.mjs --project REGA && npx wrangler d1 execute rega24-migration --remote --file prisma/d1/data/20261028_iraq_geography.sql
WITH v(slug,en,ord) AS (VALUES ('kurdistan-region','Kurdistan Region',0),('baghdad-governorate','Baghdad Governorate',1),('basra-governorate','Basra Governorate',2),('nineveh-governorate','Nineveh Governorate',3),('kirkuk-governorate','Kirkuk Governorate',4),('najaf-governorate','Najaf Governorate',5),('karbala-governorate','Karbala Governorate',6)) INSERT INTO Region (id,countryId,slug,nameEn,isActive,sortOrder,createdAt,updatedAt) SELECT 'seed_region_iq_'||slug,(SELECT id FROM Country WHERE code='IQ'),slug,en,1,ord,1793205659065,1793205659065 FROM v WHERE NOT EXISTS (SELECT 1 FROM Region r WHERE r.countryId=(SELECT id FROM Country WHERE code='IQ') AND r.slug=v.slug) AND EXISTS (SELECT 1 FROM Country WHERE code='IQ');
WITH v(slug,loc,name) AS (VALUES ('kurdistan-region','en','Kurdistan Region'),('kurdistan-region','de','Autonome Region Kurdistan'),('kurdistan-region','ckb','هەرێمی کوردستان'),('kurdistan-region','kmr','Herêma Kurdistanê'),('kurdistan-region','ar','إقليم كوردستان'),('kurdistan-region','fa','اقلیم کردستان'),('kurdistan-region','tr','Kürdistan Bölgesi'),('baghdad-governorate','en','Baghdad Governorate'),('baghdad-governorate','de','Gouvernement Bagdad'),('baghdad-governorate','ckb','پارێزگای بەغدا'),('baghdad-governorate','kmr','Parêzgeha Bexdayê'),('baghdad-governorate','ar','محافظة بغداد'),('baghdad-governorate','fa','استان بغداد'),('baghdad-governorate','tr','Bağdat Valiliği'),('basra-governorate','en','Basra Governorate'),('basra-governorate','de','Gouvernement Basra'),('basra-governorate','ckb','پارێزگای بەسرە'),('basra-governorate','kmr','Parêzgeha Besrayê'),('basra-governorate','ar','محافظة البصرة'),('basra-governorate','fa','استان بصره'),('basra-governorate','tr','Basra Valiliği'),('nineveh-governorate','en','Nineveh Governorate'),('nineveh-governorate','de','Gouvernement Ninawa'),('nineveh-governorate','ckb','پارێزگای نەینەوا'),('nineveh-governorate','kmr','Parêzgeha Neynewayê'),('nineveh-governorate','ar','محافظة نينوى'),('nineveh-governorate','fa','استان نینوا'),('nineveh-governorate','tr','Ninova Valiliği'),('kirkuk-governorate','en','Kirkuk Governorate'),('kirkuk-governorate','de','Gouvernement Kirkuk'),('kirkuk-governorate','ckb','پارێزگای کەرکووک'),('kirkuk-governorate','kmr','Parêzgeha Kerkûkê'),('kirkuk-governorate','ar','محافظة كركوك'),('kirkuk-governorate','fa','استان کرکوک'),('kirkuk-governorate','tr','Kerkük Valiliği'),('najaf-governorate','en','Najaf Governorate'),('najaf-governorate','de','Gouvernement Nadschaf'),('najaf-governorate','ckb','پارێزگای نەجەف'),('najaf-governorate','kmr','Parêzgeha Necefê'),('najaf-governorate','ar','محافظة النجف'),('najaf-governorate','fa','استان نجف'),('najaf-governorate','tr','Necef Valiliği'),('karbala-governorate','en','Karbala Governorate'),('karbala-governorate','de','Gouvernement Kerbela'),('karbala-governorate','ckb','پارێزگای کەربەلا'),('karbala-governorate','kmr','Parêzgeha Kerbelayê'),('karbala-governorate','ar','محافظة كربلاء'),('karbala-governorate','fa','استان کربلا'),('karbala-governorate','tr','Kerbela Valiliği')), x AS (SELECT r.id rid, v.* FROM v JOIN Region r ON r.slug=v.slug AND r.countryId=(SELECT id FROM Country WHERE code='IQ')) INSERT INTO RegionTranslation (id,regionId,locale,name) SELECT 'seed_rt_iq_'||slug||'_'||loc,rid,loc,name FROM x WHERE NOT EXISTS (SELECT 1 FROM RegionTranslation t WHERE t.regionId=x.rid AND t.locale=x.loc) AND EXISTS (SELECT 1 FROM Country WHERE code='IQ');
WITH v(slug,reg,en,ckb,kmr,de,fa,ar,tr,ord,lat,lng,fkmr,fde,ftr) AS (VALUES ('duhok','kurdistan-region','Duhok','دهۆک','Duhok','Dohuk','دهوک','دهوك','Duhok',22,36.8669,42.9503,'duhok','dohuk','duhok'),('halabja','kurdistan-region','Halabja','هەڵەبجە','Helebce','Halabdscha','حلبچه','حلبجة','Halepçe',23,35.1778,45.9861,'helebce','halabdscha','halepçe'),('ankawa','kurdistan-region','Ankawa','عەنکاوە','Enkawa','Ankawa','عینکاوه','عنكاوا','Ankawa',24,36.2297,43.9947,'enkawa','ankawa','ankawa'),('zakho','kurdistan-region','Zakho','زاخۆ','Zaxo','Zakho','زاخو','زاخو','Zaho',25,37.1442,42.6872,'zaxo','zakho','zaho'),('ranya','kurdistan-region','Ranya','ڕانیە','Ranye','Ranya','رانیه','رانية','Ranya',26,36.255,44.8828,'ranye','ranya','ranya'),('koya','kurdistan-region','Koya','کۆیە','Koye','Koya','کویه','كويسنجق','Koysancak',27,36.0828,44.6283,'koye','koya','koysancak'),('soran','kurdistan-region','Soran','سۆران','Soran','Soran','سوران','سوران','Soran',28,36.6528,44.5442,'soran','soran','soran'),('akre','kurdistan-region','Akre','ئاکرێ','Akrê','Akre','عقره','عقرة','Akre',29,36.7414,43.8931,'akrê','akre','akre'),('shaqlawa','kurdistan-region','Shaqlawa','شەقڵاوە','Şeqlawe','Shaqlawa','شقلاوه','شقلاوة','Şaklava',30,36.4053,44.3203,'şeqlawe','shaqlawa','şaklava'),('chamchamal','kurdistan-region','Chamchamal','چەمچەماڵ','Çemçemal','Chamchamal','چمچمال','جمجمال','Çemçemal',31,35.5333,44.8333,'çemçemal','chamchamal','çemçemal'),('kalar','kurdistan-region','Kalar','کەلار','Kelar','Kalar','کلار','كلار','Kelar',32,34.629,45.3222,'kelar','kalar','kelar'),('darbandikhan','kurdistan-region','Darbandikhan','دەربەندیخان','Derbendîxan','Darbandikhan','دربندیخان','دربندخان','Derbendihan',33,35.1128,45.6878,'derbendîxan','darbandikhan','derbendihan'),('kifri','','Kifri','کفری','Kifrî','Kifri','کفری','كفري','Kifri',34,34.6896,44.9606,'kifrî','kifri','kifri'),('baghdad','baghdad-governorate','Baghdad','بەغدا','Bexda','Bagdad','بغداد','بغداد','Bağdat',35,33.3152,44.3661,'bexda','bagdad','bağdat'),('basra','basra-governorate','Basra','بەسرە','Besra','Basra','بصره','البصرة','Basra',36,30.5085,47.7804,'besra','basra','basra'),('mosul','nineveh-governorate','Mosul','مووسڵ','Mûsil','Mossul','موصل','الموصل','Musul',37,36.34,43.13,'mûsil','mossul','musul'),('kirkuk','kirkuk-governorate','Kirkuk','کەرکووک','Kerkûk','Kirkuk','کرکوک','كركوك','Kerkük',38,35.4681,44.3922,'kerkûk','kirkuk','kerkük'),('najaf','najaf-governorate','Najaf','نەجەف','Necef','Nadschaf','نجف','النجف','Necef',39,32.0259,44.3462,'necef','nadschaf','necef'),('karbala','karbala-governorate','Karbala','کەربەلا','Kerbela','Kerbela','کربلا','كربلاء','Kerbela',40,32.616,44.0249,'kerbela','kerbela','kerbela')) INSERT INTO City (id,countryId,regionId,slug,nameEn,nameCkb,nameKmr,nameDe,nameFa,nameAr,nameTr,sortOrder,latitude,longitude,isActive,createdAt,updatedAt,foldedNameEn,foldedNameCkb,foldedNameKmr,foldedNameDe,foldedNameFa,foldedNameAr,foldedNameTr,foldedSlug) SELECT 'seed_city_iq_'||slug,(SELECT id FROM Country WHERE code='IQ'),(SELECT r.id FROM Region r WHERE r.countryId=(SELECT id FROM Country WHERE code='IQ') AND r.slug=v.reg),slug,en,ckb,kmr,de,fa,ar,tr,ord,lat,lng,1,1793205659065,1793205659065,lower(en),ckb,fkmr,fde,fa,ar,ftr,slug FROM v WHERE NOT EXISTS (SELECT 1 FROM City c WHERE c.slug=v.slug OR (c.countryId=(SELECT id FROM Country WHERE code='IQ') AND c.nameEn=v.en)) AND EXISTS (SELECT 1 FROM Country WHERE code='IQ');
